Ext._define('cif.teaching.TeachingGrid', {
    extend: 'core.RestfulGrid',

    restWindow: 'cif.teaching.TeachingWindow',

    configOrderToolBar: ['add', 'edit', 'remove', 'confirmNotTeaching','confirmCheck', '-', 'search',],

    getConfirmNotTeachingAction: function(cfg) {
        if(!this.actionNotTeaching)
            this.actionNotTeaching = Ext._create('Ext.Button', {
                text: 'Não exerce docência',
                iconCls: 'icon-cif icon-cif-book-minus',
                scope: this,
                handler: this.confirmNotTeaching
            });

        return this.actionNotTeaching;
    },

    getConfirmCheckAction: function(cfg) {
        if(!this.actionconfirm)
            this.actionconfirm = Ext._create('Ext.Button', {
                text: 'Confirmar Informação',
                iconCls: 'icon-cif icon-cif-accept',
                scope: this,
                handler: this.confirmAction
            });

        return this.actionconfirm;
    },

    confirmNotTeaching: function(){

        console.log(this.idMember);
        var rest = this.factoryRestful();
        var mask = new Ext.LoadMask(this.getEl(), {msg: 'Persistindo dados...'});

        mask.show();

        rest.doRequest(
            rest.getRoute('confirm_not_teaching', false, 'POST', {
                scope: this,
                params: {
                    pk_member: this.idMember
                },
                callback: function() {
                    mask.hide();
                    mask = undefined;
                },
                success: function(xhr) {
                    var rst = Ext.decode(xhr.responseText);

                    if(rst.success) {
                        this.getStore().reload();
                        Ext.Msg.show({
                            title: 'Atenção',
                            icon: Ext.Msg.INFO,
                            buttons: Ext.Msg.OK,
                            msg: rst.message
                        });
                    }
                    else
                        Ext.Msg.show({
                            title: 'Atenção',
                            icon: Ext.Msg.ERROR,
                            buttons: Ext.Msg.OK,
                            msg: rst.message
                        });
                },
                failure: function(xhr) {
                    Ext.Msg.show({
                        title: 'Atenção',
                        icon: Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK,
                        msg: 'Recurso indisponível no momento.'
                    });
                },
            })
        );
    },

    confirmAction: function(){
        var selection = this.getSelectionModel().getSelections();

        var rest = this.factoryRestful();
        var mask = new Ext.LoadMask(this.getEl(), {msg: 'Persistindo dados...'});

        if(selection.length > 0) {
            mask.show();

            rest.doRequest(
                rest.getRoute('confirm_action', false, 'POST', {
                    scope: this,
                    params: {
                        pks: selection.map(function(item) { return item.get('pk'); })
                    },
                    callback: function() {
                        mask.hide();
                        mask = undefined;
                    },
                    success: function(xhr) {
                        var rst = Ext.decode(xhr.responseText);

                        if(rst.success) {
                            this.getStore().reload();
                            Ext.Msg.show({
                                title: 'Atenção',
                                icon: Ext.Msg.INFO,
                                buttons: Ext.Msg.OK,
                                msg: rst.message
                            });
                        }
                        else
                            Ext.Msg.show({
                                title: 'Atenção',
                                icon: Ext.Msg.ERROR,
                                buttons: Ext.Msg.OK,
                                msg: rst.message
                            });
                    },
                    failure: function(xhr) {
                        Ext.Msg.show({
                            title: 'Atenção',
                            icon: Ext.Msg.ERROR,
                            buttons: Ext.Msg.OK,
                            msg: 'Recurso indisponível no momento.'
                        });
                    },
                })
            );
        }
        else Ext.Msg.show({
            'title': 'Atenção',
            'icon': Ext.Msg.ERROR,
            'buttons': Ext.Msg.OK,
            'msg': 'Selecione pelo menos um item.'
        });
    },

    getColumnModel: function() {
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    Ext._create('Ext.grid.RowNumberer'),
                    {header: '', dataIndex: 'status', id: 'autoExpandColumn', hidden: true},
                    {header: '', dataIndex: 'icons', width: 150, renderer: core.rendererIconGrid},
                    {header: 'Modalidade', dataIndex: 'modality_display', width: 100},
                    {header: 'Disciplina', dataIndex: 'discipline_unicode', width: 220},
                    {header: 'Horários', dataIndex: 'schedules', width:400},
                    {header: 'Instituição de Ensino', dataIndex: 'educational_institution_unicode', width:350},
                    {header: 'Carga Horária', dataIndex: 'work_hours', width: 80},
                    {header: 'Data Início Docência', dataIndex: 'start_date', width: 120, renderer: Ext.util.Format.dateRenderer('d/m/Y')},
                    {header: 'Data Fim Docência', dataIndex: 'end_date', width: 120, renderer: Ext.util.Format.dateRenderer('d/m/Y')},
                    {header: 'Referência', dataIndex: 'refperiod_teaching_unicode', width: 200},
                    {header: 'Criado em', dataIndex: 'created_at', width: 150, renderer: Ext.util.Format.dateRenderer('d/m/Y') , hidden: true},
                    {header: 'Criado por', dataIndex: 'created_by_unicode', width: 150, hidden: true},
                    {header: 'Atualizado em', dataIndex: 'modified_at', width: 150, renderer: Ext.util.Format.dateRenderer('d/m/Y') , hidden: true},
                    {header: 'Modificado por', dataIndex: 'modified_by_unicode', width: 150, hidden: true},
                ]
            );

        return this._columnModel;
    },

    cleanFilter: function() {
        this._filterStatus = [1];
        this.setFilter([{'property': 'refperiod_teaching__status_period__in', 'value': this._filterStatus, 'stage': 1000},]);

    },

    toggleStatus: function(tipo) {
        if(this._filterStatus.indexOf(tipo) >= 0)
            this._filterStatus.remove(tipo);
        else
            this._filterStatus.push(tipo);

        this.setFilterProperty('status__in', this._filterStatus, 1000);
    },

     getFilterMenu: function() {
        if(!this._filterMenu)
            this._filterMenu = [
                {
                    text: 'Ativos',
                    checked: true,
                    scope: this,
                    hideOnClick: false,
                    handler: function() { this.toggleStatus(1); }
                },
                {
                    text: 'Inativos',
                    checked: false,
                    scope: this,
                    hideOnClick: false,
                    handler: function() { this.toggleStatus(2); }
                },
            ];

        return this._filterMenu;
    },

    constructor: function(cfg) {
        cfg = core.nullValue(cfg, {});

        Ext.apply(
            cfg,
             {
                'viewConfig': {
                    getRowClass: function(record, rowIndex, rp, ds){ // rp = rowParams

                        if(record.data.refperiod_status == 0)
                            return '';
                        if(record.data.refperiod_status == 1)
                            // return 'x-grid3-green-simple';
                            return '';
                        if(record.data.refperiod_status == 2)
                            return 'x-grid3-red-simple';
                    }
                }
            }
        );

        this.cleanFilter();
        cif.teaching.TeachingGrid.superclass.constructor.call(this, cfg);
    }

});

core.RestfulGrid.register(
    'cif.teaching.TeachingRestful',
    'cif.teaching.TeachingGrid'
);

